import horizon

def parse(line):
    """'volume = 75' -> ('volume', 75.0). Positions count from 0."""
    eq = horizon.string.find(line, "=")
    if eq < 0:
        return None
    key = horizon.string.trim(horizon.string.substring(line, 0, eq))
    rest = horizon.string.substring(line, eq + 1, horizon.string.length(line))
    return key, horizon.string.toNumber(rest)

class Settings(horizon.Behavior):
    def on_start(self):
        parsed = parse("volume = 75")
        if parsed:
            key, value = parsed
            horizon.log(f"{key} is {value}")

import horizon

class PauseMenu(horizon.Behavior):
    # "Pause" is an input action with "Fires while the game is paused"
    # ticked; without it the second press would never arrive.
    def on_input_pressed(self, name):
        if name != "Pause":
            return
        if horizon.time.isPaused():
            horizon.time.resume()
        else:
            horizon.time.pause()

    def on_collision_enter(self, other):
        horizon.time.hitStop(0.1)   # a landed hit freezes for a tenth of a second

import horizon

class Reminders(horizon.Behavior):
    def on_start(self):
        self.autosave = horizon.timer.every(30)
        self.hint = horizon.timer.after(5)

    def on_timer(self, handle):
        if handle == self.autosave:
            horizon.log("autosave")
        elif handle == self.hint:
            horizon.log("Press E to open the door")
        # any other handle belongs to another script

import horizon

LIMIT = 90  # seconds for the level

# This script sits on the HUD's UI Text entity.
class LevelClock(horizon.Behavior):
    def on_start(self):
        self.left = LIMIT

    def on_update(self, dt):
        if self.left <= 0:
            return
        self.left = max(0.0, self.left - dt)
        e = self.entity_id
        horizon.ui.setText(e, "%d:%02d" % (self.left // 60, int(self.left) % 60))
        if self.left < 10:
            horizon.ui.setColor(e, 1, 0.25, 0.2, 1)   # a colour is four numbers
        if self.left == 0:
            horizon.ui.setVisible(e, False)

import horizon

# Store the PREFERENCE, not the mode: System is a rule that follows the desktop.
NEXT = {"System": "Light", "Light": "Dark", "Dark": "System"}

class ThemeToggle(horizon.Behavior):
    def on_start(self):
        horizon.theme.setMode(horizon.prefs.getString("theme", "System"))
        horizon.theme.setFontScale(horizon.prefs.getNumber("textScale", 1))

    def on_input_pressed(self, name):
        if name == "CycleTheme":
            pref = NEXT[horizon.theme.getPreference()]
            horizon.theme.setMode(pref)
            horizon.prefs.setString("theme", pref)
            horizon.log("theme %s, showing %s" % (pref, horizon.theme.getMode()))
        elif name in ("BiggerText", "SmallerText"):
            step = 0.25 if name == "BiggerText" else -0.25
            horizon.theme.setFontScale(horizon.theme.getFontScale() + step)   # kept in 0.5..3
            horizon.prefs.setNumber("textScale", horizon.theme.getFontScale())

import horizon

MANUAL = "https://example.com/manual/"

class OpenManual(horizon.Behavior):
    def on_input_pressed(self, name):
        if name != "Help":
            return
        # openUrl needs "Run other programs". Without it, hand the address over.
        if horizon.process.openUrl(MANUAL):
            return
        horizon.clipboard.setText(MANUAL)
        horizon.dialog.message("Manual", "The manual's address is on your clipboard:\n" + MANUAL, 0)

import horizon
import json

PLAYER = "Player 1"

class Highscores(horizon.Behavior):
    def on_start(self):
        # Lands in the project's Saved folder, but needs the "Files outside the
        # project" permission all the same (see the group notes).
        self.db = horizon.db.open("scores.db")
        if self.db:
            horizon.db.exec(self.db, "CREATE TABLE IF NOT EXISTS scores(name TEXT, points INTEGER)", "")

    def on_input_pressed(self, name):
        if name != "LevelDone" or not self.db:
            return
        points = max(0, 1000 - int(horizon.time.elapsed() * 10))
        # Values travel as a JSON array behind the ?s, never pasted into the SQL.
        if not horizon.db.exec(self.db, "INSERT INTO scores(name, points) VALUES(?, ?)",
                               json.dumps([PLAYER, points])):
            horizon.log("scores: " + horizon.db.lastError(self.db))
            return
        rows = json.loads(horizon.db.query(
            self.db, "SELECT name, points FROM scores ORDER BY points DESC LIMIT 5", ""))
        for i, row in enumerate(rows, 1):
            horizon.log("%d. %s  %d" % (i, row["name"], row["points"]))

import horizon

class BossGate(horizon.Behavior):
    # Opens the gate once the boss is gone. Look the ids up once, not every
    # frame: findByName walks every named entity.
    def on_start(self):
        self.boss = horizon.entity.findByName("Boss")
        self.gate = horizon.entity.findByName("Gate")

    def on_update(self, dt):
        if self.gate != 0 and not horizon.entity.exists(self.boss):
            horizon.entity.destroy(self.gate)   # takes its children along
            self.gate = 0

import horizon

class CaveStream(horizon.Behavior):
    # This entity is a trigger volume at the start of the corridor. The cave
    # loads hidden, 200 m along X, while the player walks; the door shows it.
    def on_start(self):
        self.zone = 0

    def on_begin_overlap(self, other):
        if self.zone:
            return
        # The position takes FOUR numbers from a script; the fourth is ignored.
        self.zone = horizon.scene.loadAdditive("Scenes/Cave.hescene", True, 200, 0, 0, 0)

    # "Interact" is an input action.
    def on_input_pressed(self, name):
        if name == "Interact" and self.zone:
            horizon.scene.showZone(self.zone)   # queued behind the load

import horizon

class TutorialHint(horizon.Behavior):
    def on_start(self):
        if not horizon.prefs.getBool("tutorial.skip", False):
            horizon.log("Tutorial: press Space to jump")

    # "SkipTutorial" is an input action, e.g. on the hint's close button.
    def on_input_pressed(self, name):
        if name == "SkipTutorial":
            horizon.prefs.setBool("tutorial.skip", True)   # on disk at once

import horizon

FLOOR = -20   # below this height the character has fallen out

class KillPlane(horizon.Behavior):
    def on_start(self):
        self.spawn = horizon.getPosition(self.entity_id)

    def on_update(self, dt):
        _, y, _ = horizon.getPosition(self.entity_id)
        if y < FLOOR:
            # Back to where the level started it, without the speed of the fall.
            horizon.physics.setPositionAndReset(self.entity_id, *self.spawn)

import horizon

# On an entity with a Nav Agent. World positions on the baked NavMesh.
POINTS = [(6, 0, -6), (6, 0, 6), (-6, 0, 6)]

class Patrol(horizon.Behavior):
    def on_start(self):
        self.i = -1
        self.go_next()

    def go_next(self):
        self.i = (self.i + 1) % len(POINTS)
        if not horizon.nav.moveTo(self.entity_id, *POINTS[self.i]):
            horizon.log(f"patrol point {self.i} is not reachable")

    def on_update(self, dt):
        # isMoving turns false on arrival (and after a refusal).
        if not horizon.nav.isMoving(self.entity_id):
            self.go_next()

import horizon

class Inventory(horizon.Behavior):
    open = False

    # "Inventory" is a button action. While the inventory is open the cursor
    # is visible and clicks go to the UI; the game still reads the keys.
    def on_input_pressed(self, name):
        if name != "Inventory":
            return
        self.open = not self.open
        if self.open:
            horizon.input.setModeGameAndUI()
            horizon.showCursor()
        else:
            horizon.input.setModeGameOnly()
            horizon.hideCursor()

import horizon

class Impact(horizon.Behavior):
    # On a crate with a Particle System whose graph does not loop (sparks):
    # every hit fires a handful of sparks and gives the camera a short jolt.
    def on_collision_enter(self, other):
        made = horizon.particle.burst(self.entity_id, 24)
        if made > 0:
            # 5 cm, 0.5 degrees, 18 shakes per second, a quarter of a second.
            horizon.camera.playShake(0.05, 0.5, 18, 0.25)

import horizon

MUSIC = "Audio/theme.hasset"
VOLUME, FADE = 0.6, 2.0   # fade length in seconds

class MusicFade(horizon.Behavior):
    def on_start(self):
        self.music = horizon.audio.play(MUSIC, VOLUME, 1, True)
        self.left = 0.0

    # "EndLevel" is a button action.
    def on_input_pressed(self, name):
        if name == "EndLevel" and self.music != 0:
            self.left = FADE

    def on_update(self, dt):
        if self.left <= 0:
            return
        self.left -= dt
        if self.left <= 0:
            horizon.audio.stop(self.music)   # stop, not volume 0: frees the voice
            self.music = 0
        else:
            horizon.audio.setVolume(self.music, VOLUME * self.left / FADE)

import horizon

class SprintFov(horizon.Behavior):
    # "Sprint" is a button action. The kick widens the view for a moment and
    # falls back by itself; getFov keeps answering the authored value.
    def on_input_pressed(self, name):
        if name == "Sprint":
            horizon.camera.kickFov(8, 0.15, 0.6, 0.4)   # degrees, attack, hold, decay
            horizon.camera.setLagEnabled(True)           # the camera trails a little

    def on_input_released(self, name):
        if name == "Sprint":
            horizon.camera.setLagEnabled(False)
